int timMax(const int a[], int n){
    int res = a[0];
    for(int i = 1; i < n; i++)
        if(a[i] > res) res = a[i];
    return res;
}

void nhapMang(int a[], int *n){
    scanf("%d", n);
    for(int i = 0; i < *n; i++) scanf("%d", &a[i]);
}
void xuatMang(const int a[], int n){
    for(int i = 0; i < n; i++) printf("%d ", a[i]);
}

int a[1000], n;
nhapMang(a, &n);
xuatMang(a, n);

void binhPhuong(const int a[], int kq[], int n){
